var FleetViolationUtils = Class.create();

/**
 * FLEET-30 V7 hook (D-19). Returns false ("not blocked") until FLEET-47 replaces it with the
 * real check: unpaid violation older than violation.block_days for the user.
 * @param {string} userSysId
 * @returns {boolean}
 */
FleetViolationUtils.isBlocked = function(userSysId) {
    return false;
};

FleetViolationUtils.prototype = {
    initialize: function() {},
    type: 'FleetViolationUtils'
};
